actions.script:
const found = ec.service.sync().name('org.moqui.devaide.ArtifactServices.search#Artifacts')
    .parameters({text: String(term || ''), kinds: 'service', limit: 20}).call() || {}
const options = (found.artifacts || []).map((row) => row.name || String(row.id || '').replace(/^service:/, ''))
    .map((name) => ({value: name, label: name}))
const asked = String(term || '')
ec.message.clearErrors()
ec.web.sendJsonResponse(asked && !options.some((option) => option.value === asked) && asked.indexOf('#') > 0
    ? [{value: asked, label: asked}].concat(options) : options)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const service = guided.serviceContext(artifact)
const set = service.ops.pure.setAttributeOps
const ops = service.node ? [].concat(set(service.node, 'authenticate', authenticate === 'true' ? '' : authenticate),
    set(service.node, 'allow-remote', allowRemote === 'true' ? 'true' : ''), set(service.node, 'transaction', transactionType),
    set(service.node, 'transaction-timeout', transactionTimeout)) : []
if (!service.node) ec.message.addError(ec.l10n.localize('The service is not defined in a file of its own here'))
else guided.apply(service.target, service.file, ops)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const service = guided.serviceContext(artifact)
if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(String(parameterName || ''))) ec.message.addError(ec.l10n.localize('A parameter name is letters, digits and _'))
else if (!service.node) ec.message.addError(ec.l10n.localize('The service is not defined in a file of its own here'))
else {
    // with parentPath (its names, dotted), inside that parameter: a Map's or a List's
    const holder = which === 'out-parameters' ? 'out-parameters' : 'in-parameters'
    const parent = String(parentPath || '')
    if (parent && !service.ops.service.parameterNode(service.node, holder, parent)) ec.message.addError('No parameter ' + parent + ' to add it in')
    else guided.apply(service.target, service.file, service.ops.service.addParameter(service.node, holder,
        {name: parameterName, type: parameterType, required: required === 'true', defaultValue, description}, parent))
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const service = guided.serviceContext(artifact)
if (!service.node) ec.message.addError(ec.l10n.localize('The service is not defined in a file of its own here'))
else guided.apply(service.target, service.file, service.ops.service.editParameter(service.node, which === 'out-parameters' ? 'out-parameters' : 'in-parameters',
    [parentPath, parameterName].filter((part) => part).join('.'), {type: parameterType, required: required === 'true', defaultValue, description}))

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const service = guided.serviceContext(artifact)
if (!service.node) ec.message.addError(ec.l10n.localize('The service is not defined in a file of its own here'))
else guided.apply(service.target, service.file, service.ops.service.removeParameter(service.node, which === 'out-parameters' ? 'out-parameters' : 'in-parameters',
    [parentPath, parameterName].filter((part) => part).join('.')))

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const service = guided.serviceContext(artifact)
if (!service.secas) ec.message.addError(ec.l10n.localize('Create a site component on Home first: a SECA rule goes in its secas file'))
else guided.apply(service.target, service.secas, service.ops.service.addRule((service.secasFile || {}).outline,
    service.ops.service.secaXml(service.serviceName, when || 'post-service', condition, callService)))

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const ops = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedOps.js')
const serviceName = String(artifact || '').replace(/^service:/, '')
const viewOut = guided.probe('org.moqui.devaide.ServiceWriterServices.get#ServiceView', {serviceName})
const inParameters = (viewOut.view && viewOut.view.service && viewOut.view.service.inParameters) || []
const values = {}
for (const parameter of inParameters) {
    const value = ec.web.parameters[parameter.name]
    if (value != null && String(value) !== '') values[parameter.name] = String(value)
}
ec.web.sessionAttributes['DevAideTry.values.' + serviceName] = JSON.stringify(values)
const real = !!runReal
const parameters = ops.service.tryParameters(values, inParameters)
const out = ec.service.sync().name('org.moqui.devaide.ServiceWriterServices.try#Service')
    .parameters({serviceName, parameters: JSON.stringify(parameters), real, confirm: real}).call() || {}
if (!ec.message.hasError()) {
    ec.web.sessionAttributes['DevAideTry.result.' + serviceName] = JSON.stringify(Object.assign({parameters}, out.result || {}))
    // the run's own word, not the "Saved" a form's post says by default
    // a run that failed says so on the message line too: the result below says why
    const failed = (out.result || {}).failed
    ec.message.addMessage(ec.l10n.localize(failed ? (real ? 'The run failed' : 'The run in the sim failed: nothing kept')
        : (real ? 'Ran for real' : 'Ran in the sim: nothing kept')), failed ? 'warning' : 'info')
}

const serviceName = String(artifact || '').replace(/^service:/, '')
let result = null
try { result = JSON.parse(ec.web.sessionAttributes['DevAideTry.result.' + serviceName] || 'null') } catch (err) { result = null }
if (!result || !result.sim || result.failed) ec.message.addError(ec.l10n.localize('Run it in the sim first: a spec is made from a Try that passed'))
else {
    const out = ec.service.sync().name('org.moqui.devaide.ServiceWriterServices.save#TrySpec').parameters({serviceName,
        parameters: JSON.stringify(result.parameters || {}), out: JSON.stringify(result.out || {}), rows: JSON.stringify(result.rows || [])}).call() || {}
    if (!ec.message.hasError()) {
        ec.web.sessionAttributes['DevAideTry.spec.' + serviceName] = JSON.stringify({rootId: out.rootId, path: out.path, name: out.spec})
        ec.message.addMessage('Saved as a feature of ' + out.path, 'success')
    }
}

const serviceName = String(artifact || '').replace(/^service:/, '')
let spec = null
try { spec = JSON.parse(ec.web.sessionAttributes['DevAideTry.spec.' + serviceName] || 'null') } catch (err) { spec = null }
if (!spec) ec.message.addError(ec.l10n.localize('Save a Try as a spec first'))
else {
    const out = ec.service.sync().name('org.moqui.devaide.ServiceWriterServices.run#Spec').parameters({rootId: spec.rootId, path: spec.path}).call() || {}
    if (!ec.message.hasError()) ec.web.sessionAttributes['DevAideTry.specRun.' + serviceName] = JSON.stringify(out)
}

const serviceName = String(artifact || '').replace(/^service:/, '')
const body = String(ec.web.secureRequestParameters.snippetBody || snippetBody || '')
const language = snippetLanguage === 'javascript' ? 'javascript' : 'xml'
let values = {}
try { values = JSON.parse(ec.web.sessionAttributes['DevAideTry.values.' + serviceName] || '{}') } catch (err) { values = {} }
const out = ec.service.sync().name('org.moqui.devaide.ServiceWriterServices.try#Snippet')
    .parameters({language, body, parameters: JSON.stringify(values)}).call() || {}
ec.web.sessionAttributes['DevAideTry.snippet.' + serviceName] = JSON.stringify({language, body, result: out.result || null})
if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize((out.result || {}).failed
    ? 'The snippet failed in the sim: nothing kept' : 'Ran the snippet in the sim: nothing kept'), (out.result || {}).failed ? 'warning' : 'info')

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js') const service = guided.serviceContext(artifact) serviceName = service.serviceName view = service.view readError = service.refused || '' target = service.target tab = ['try', 'overview', 'parameters', 'implementation', 'rules', 'changes'].includes(tab) ? tab : 'try' definition = (view && view.service) || {} const node = service.node const attr = (name) => node ? service.ops.pure.attrOf(node, name) : undefined serviceFile = service.serviceFile || {} canEdit = !!(view && view.tier !== 'view' && service.serviceFile && !service.serviceFile.readOnly && node) readOnlyReason = view && !canEdit ? (service.serviceFile && service.serviceFile.readOnlyReason) || (node ? '' : 'Its definition is not a service element of a file here (' + (definition.kind || 'unknown') + ')') : '' pendingText = guided.pendingText(service.buffer) bufferExpired = !!service.buffer.expired const left = guided.taken(target) conflict = left.conflict || null problemRows = (left.problems || []).map((problem) => ({file: problem.file || '', line: problem.line || 0, severity: problem.severity || '', message: problem.message || ''})) headerText = view ? [definition.kind, view.artifact ? view.artifact.component + (view.artifact.upstream ? ' (upstream)' : ' (site)') : '', 'used by ' + (view.usedByCount || 0), view.calls != null ? view.calls + ' calls in the last spec run' : ''].filter((part) => part).join(' · ') : '' workspaceUrl = (view && view.artifact && view.artifact.url) || '' refsUrl = '/qapps/dev/Artifacts/Refs?artifactId=' + encodeURIComponent('service:' + serviceName) const tabUrl = (name) => sri.buildUrl('../Edit').addParameters({artifact: 'service:' + serviceName, tab: name}).getUrlWithParams() tabItems = [['try', 'Try'], ['overview', 'Overview'], ['parameters', 'Parameters ' + ((definition.inParameters || []).length) + ' in, ' + ((definition.outParameters || []).length) + ' out'], ['implementation', 'Implementation'], ['rules', 'SECA rules ' + ((view && view.secas) || []).length], ['changes', 'Changes' + (service.buffer.pending.count ? ' ' + service.buffer.pending.count : '')]] .map(([name, title]) => ({title, url: tabUrl(name), active: name === tab}))
// Try: the last values, result, spec and snippet of this service, kept in the session const kept = (name, fallback) => { try { return JSON.parse(ec.web.sessionAttributes['DevAideTry.' + name + '.' + serviceName] || 'null') || fallback } catch (err) { return fallback } } tryValues = kept('values', {}) tryResult = kept('result', null) tryJson = tryResult && tryResult.out ? JSON.stringify(tryResult.out, null, 2) : '' tryRows = ((tryResult && tryResult.rows) || []).map((row) => ({entity: row.entity, action: row.action, key: JSON.stringify(row.key || {}), fields: (row.fields || []).map((f) => f.field + (f.before !== undefined ? ': ' + f.before + ' → ' : ': ') + f.after).join('; ')})) tryLog = ((tryResult && tryResult.log) || []).join('\n') tryNote = tryResult ? (tryResult.sim ? 'In sim, nothing kept' : 'For real') + (tryResult.millis != null ? ' · ' + tryResult.millis + ' ms' : '') : '' trySpec = kept('spec', null) specRun = kept('specRun', null) specCases = ((specRun && specRun.cases) || []).map((item) => ({outcome: item.outcome, name: item.name, message: item.message || ''})) snippet = kept('snippet', {language: 'xml', body: '<actions>\n <set field="result" from="1 + 1"/>\n</actions>', result: null}) snippetValues = {snippetLanguage: snippet.language, snippetBody: snippet.body} hasSim = !!(view && view.sim) canTryReal = !!(view && view.tier !== 'view')
// Overview: the element's attributes as staged, else the definition's settingsValues = {authenticate: attr('authenticate') || definition.authenticate || 'true', allowRemote: attr('allow-remote') === 'true' ? 'true' : '', transactionType: attr('transaction') || '', transactionTimeout: attr('transaction-timeout') || ''} implementsText = (definition.implements || []).join(', ') inRows = view ? guided.parameterRows(service, 'in-parameters') : [] outRows = view ? guided.parameterRows(service, 'out-parameters') : []
// the Implementation, read only: the actions as staged and their JavaScript const actions = node ? service.ops.pure.children(node, ['actions'])[0] : null actionsXml = actions && serviceFile.text ? serviceFile.text.slice(actions.from16, actions.to16) : '' generatedJs = '' if (tab === 'implementation' && actionsXml) { const generated = guided.probe('org.moqui.devaide.ServiceWriterServices.get#GeneratedJs', {xml: actionsXml}) generatedJs = generated.error ? '// ' + generated.error : generated.source || generated.refused || '' } scriptUrl = view && view.script && view.script.rootId ? '/qapps/dev/Workspace?rootId=' + encodeURIComponent(view.script.rootId) + '&path=' + encodeURIComponent(view.script.path) : ''
// SECA rules: the active ones, each opening its file at its line secaRows = ((view && view.secas) || []).map((rule) => ({when: rule.when, priority: rule.priority, condition: rule.condition || '', actions: (rule.actions || []).join(', '), place: (rule.file || '').split('/').slice(-2).join('/') + ':' + rule.line, url: rule.open && rule.open.rootId ? '/qapps/dev/Workspace?rootId=' + encodeURIComponent(rule.open.rootId) + '&path=' + encodeURIComponent(rule.open.path) + '&line=' + rule.line : ''})) secasPath = service.secas ? service.secas.path : '' changeRows = service.buffer.files.filter((file) => file.staged).map((file) => ({path: file.path, diff: file.diff || '', changedOnDisk: !!file.changedOnDisk}))
